// Entrada do formulário → campos padronizados e validação do que cada modo exige.
// O Form Trigger 2.1 identifica cada campo pelo rótulo, e o arquivo pelo rótulo com \W → _.
// Estes rótulos precisam ser iguais aos de n8n/montar-workflow.mjs (um teste confere).
const ROTULOS = {
  certificado: 'Certificado (PDF)',
  modo: 'Declaração de autenticidade',
  nome: 'Nome completo',
  matricula: 'Matrícula',
  rg: 'RG',
  cpf: 'CPF',
  assinatura: 'Foto da assinatura (JPG ou PNG)',
  declaracao_base: 'Declaração-base (PDF)',
};
const item = $input.first();
const texto = (chave) => (typeof item.json[ROTULOS[chave]] === 'string' ? item.json[ROTULOS[chave]].trim() : '');
const recebidos = item.binary ?? {};
const arquivos = Object.fromEntries(['certificado', 'assinatura', 'declaracao_base']
  .map((chave) => [chave, recebidos[ROTULOS[chave].replace(/\W/g, '_')]])
  .filter(([, arquivo]) => arquivo));

const modo = texto('modo').startsWith('Primeira') ? 'primeiro_uso' : 'reuso';
const saida = {
  origem: 'formulario',
  modo,
  versao: 'v1',
  nome: texto('nome').replace(/\s+/g, ' '),
  matricula: texto('matricula'),
  rg: texto('rg'),
  cpf: texto('cpf'),
  erro: '',
};

const faltando = [];
if (!arquivos.certificado) faltando.push('o certificado');
if (modo === 'primeiro_uso') {
  if (!saida.nome) faltando.push('o nome completo');
  if (!saida.matricula) faltando.push('a matrícula');
  if (!saida.rg) faltando.push('o RG');
  if (!saida.cpf) faltando.push('o CPF');
  if (!arquivos.assinatura) faltando.push('a foto da assinatura');
} else if (!arquivos.declaracao_base) {
  faltando.push('a sua declaração-base (PDF que a ferramenta gerou no primeiro uso)');
}

const problemas = [];
if (faltando.length) problemas.push(`Faltou enviar ${faltando.join(', ')}.`);
if (arquivos.certificado && arquivos.certificado.mimeType !== 'application/pdf') {
  problemas.push('O certificado precisa estar em PDF.');
}
if (modo === 'reuso' && arquivos.declaracao_base && arquivos.declaracao_base.mimeType !== 'application/pdf') {
  problemas.push('A declaração-base precisa estar em PDF.');
}
if (modo === 'primeiro_uso') {
  if (arquivos.assinatura && !/^image\/(png|jpe?g)$/.test(arquivos.assinatura.mimeType)) {
    problemas.push('A assinatura precisa ser uma foto em JPG ou PNG.');
  }
  if (saida.matricula && !/^\d{6,15}$/.test(saida.matricula)) problemas.push('A matrícula deve ter só números.');
  if (saida.cpf && saida.cpf.replace(/\D/g, '').length !== 11) problemas.push('O CPF deve ter 11 dígitos.');
}
saida.erro = problemas.join(' ');

// Só segue o que o modo usa: no reuso a assinatura e os dados digitados são descartados.
const binary = { certificado: arquivos.certificado };
if (modo === 'primeiro_uso') binary.assinatura = arquivos.assinatura;
else binary.declaracao_base = arquivos.declaracao_base;
return [{ json: saida, binary }];

// Entrada da API de avaliação (POST multipart: certificado, versao, nome, matricula).
// Só classifica: não gera declaração nem PDF final.
const item = $input.first();
const corpo = item.json.body ?? {};
const certificado = item.binary?.certificado;

const versao = String(corpo.versao ?? 'v1').trim();
let erro = '';
if (!certificado) erro = 'Envie o PDF no campo "certificado".';
else if (certificado.mimeType !== 'application/pdf') erro = 'O certificado precisa estar em PDF.';
else if (!/^v\d+$/.test(versao)) erro = 'O campo "versao" deve ter o formato v1, v2...';

return [{
  json: {
    origem: 'api',
    modo: 'api',
    versao,
    nome: String(corpo.nome ?? '').trim(),
    matricula: String(corpo.matricula ?? '').trim(),
    rg: '',
    cpf: '',
    erro,
  },
  binary: certificado ? { certificado } : {},
}];

// 1º uso: preenche o Anexo I com os dados e a assinatura (data URI) para o Gotenberg converter.
const fs = require('fs');
const item = $input.first();

const escapar = (s) => String(s).replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
));

const assinatura = item.binary.assinatura;
const bytes = await this.helpers.getBinaryDataBuffer(0, 'assinatura');
let html = fs.readFileSync('/data/templates/declaracao.html', 'utf8');
for (const campo of ['nome', 'matricula', 'rg', 'cpf']) {
  html = html.replaceAll(`{{${campo}}}`, escapar(item.json[campo]));
}
html = html.replace('{{assinatura}}', `data:${assinatura.mimeType};base64,${bytes.toString('base64')}`);

const pagina = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{ json: item.json, binary: { ...item.binary, html: pagina } }];

// Guarda a declaração-base (sem data) gerada pelo Gotenberg: ela vai para o carimbo de data
// e também volta para o aluno baixar e reutilizar.
const item = $input.first();
const pdf = item.binary?.declaracao_base;
if (!pdf) {
  throw new Error(`Gotenberg não gerou a declaração: ${item.json.error?.message ?? 'sem resposta'}`);
}
const bytes = await this.helpers.getBinaryDataBuffer(0, 'declaracao_base');
const dados = $('Normalizar formulário').first().json;
return [{
  json: { ...dados, declaracao_base_b64: bytes.toString('base64') },
  binary: { declaracao_base: { ...pdf, fileName: 'minha-declaracao-base.pdf' } },
}];

// Junta o que a classificação precisa: o certificado, os dados para anonimizar e,
// no formulário, a declaração já datada pelo serviço `declaracao`.
const doFormulario = $('Normalizar formulário').isExecuted;
const normal = doFormulario ? $('Normalizar formulário').first() : $('Normalizar API').first();
const n = normal.json;

const saida = {
  origem: n.origem,
  modo: n.modo,
  versao: n.versao,
  dados_anonimizar: { nome: n.nome, matricula: n.matricula, rg: n.rg, cpf: n.cpf },
  declaracao_datada_b64: null,
  linha_data: null,
  erro: '',
};

if (doFormulario) {
  const r = $input.first().json; // resposta de /redatar (fullResponse)
  if (r.statusCode !== 200) {
    saida.erro = r.body?.erro ?? 'Não consegui colocar a data de hoje na declaração. Tente de novo.';
  } else {
    saida.declaracao_datada_b64 = r.body.pdf_base64;
    saida.linha_data = r.body.linha_data;
    if (n.modo === 'reuso') {
      // No reuso os dados vêm da própria declaração-base.
      saida.dados_anonimizar = { nome: r.body.nome, matricula: r.body.matricula, rg: r.body.rg, cpf: r.body.cpf };
    }
  }
}

return [{ json: saida, binary: { certificado: normal.binary.certificado } }];

// Troca nome, matrícula, RG, CPF e e-mails por [ALUNO] antes de o texto sair do Docker.
// O plano gratuito do Gemini pode usar o conteúdo enviado para treinar modelos.
const prep = $('Preparar certificado').first().json;
const resposta = $input.first().json; // resposta de /texto (fullResponse)

const MARCA = '[ALUNO]';
const PARTICULAS = new Set(['de', 'da', 'do', 'das', 'dos', 'e']);
const VARIANTES = {
  a: 'aáàâãä', e: 'eéèêë', i: 'iíìîï', o: 'oóòôõö', u: 'uúùûü', c: 'cç', n: 'nñ',
};

const semAcento = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const escaparRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// "José" casa com "JOSE", "jose", "José"...
function padraoPalavra(palavra) {
  return [...semAcento(palavra)].map((ch) => (VARIANTES[ch] ? `[${VARIANTES[ch]}]` : escaparRegex(ch))).join('');
}

// "123.456" casa com "123456", "123 456", "123-456"...
function padraoDigitos(valor) {
  const digitos = String(valor ?? '').replace(/\D/g, '');
  return digitos.length >= 5 ? digitos.split('').join('[\\s.\\-/]?') : null;
}

function anonimizar(texto, dados) {
  let t = texto;
  const trocar = (padrao) => {
    t = t.replace(new RegExp(padrao, 'giu'), MARCA);
  };

  const palavras = String(dados.nome ?? '').trim().split(/\s+/).filter(Boolean);
  const nomeTodo = (lista) => trocar(`(?<![\\p{L}])${lista.map(padraoPalavra).join('\\s+')}(?![\\p{L}])`);
  if (palavras.length) {
    nomeTodo(palavras);
    // Também "Primeiro Último" (ex.: "Maria Silva"). Partes soltas ficam: um sobrenome sozinho
    // costuma ser nome de instituição ("Escola Silva") e trocá-lo estragaria a descrição.
    const semParticulas = palavras.filter((p) => !PARTICULAS.has(semAcento(p)));
    if (semParticulas.length > 2) nomeTodo([semParticulas[0], semParticulas.at(-1)]);
  }
  for (const valor of [dados.matricula, dados.rg, dados.cpf]) {
    const padrao = padraoDigitos(valor);
    if (padrao) trocar(padrao);
  }
  if (dados.rg) trocar(escaparRegex(String(dados.rg)));
  // Padrões genéricos, para o que não veio nos dados (CPF de outra pessoa, matrícula etc.).
  trocar('\\b\\d{3}\\.?\\d{3}\\.?\\d{3}-?\\d{2}\\b');
  trocar('\\b\\d{9,}\\b');
  trocar('[\\w.+-]+@[\\w-]+\\.[\\w.]+');
  return t.replace(/(\[ALUNO\][\s,]*){2,}/g, `${MARCA} `);
}

if (resposta.statusCode !== 200) {
  return [{ json: { ...prep, erro: resposta.body?.erro ?? 'Não consegui ler o certificado.' } }];
}
const texto = resposta.body.texto ?? '';
if (texto.replace(/\s/g, '').length < 40) {
  return [{ json: { ...prep, erro: 'Não consegui ler o certificado, nem como imagem. Envie um PDF mais nítido: de preferência o arquivo original do emissor, ou uma digitalização reta e bem iluminada.' } }];
}
return [{ json: { ...prep, texto_anonimizado: anonimizar(texto, prep.dados_anonimizar), dados_anonimizar: undefined } }];

// Monta a chamada ao Gemini lendo o prompt e o schema versionados em prompts/.
const fs = require('fs');
const j = $input.first().json;

if (!/^v\d+$/.test(j.versao)) throw new Error(`Versão de prompt inválida: ${j.versao}`);
const arquivo = `/data/prompts/classificacao/${j.versao}.md`;
if (!fs.existsSync(arquivo)) throw new Error(`Prompt ${j.versao} não existe em prompts/classificacao/`);

const prompt = fs.readFileSync(arquivo, 'utf8');
const schema = JSON.parse(fs.readFileSync('/data/prompts/classificacao/schema.json', 'utf8'));
// O certificado não pode fechar a tag e "sair" da área de dados.
const certificado = j.texto_anonimizado.replace(/<\/?\s*certificado\s*>/gi, '');

return [{
  json: {
    ...j,
    modelo: $env.GEMINI_MODEL || 'gemini-3.5-flash-lite',
    simular: !$env.GEMINI_API_KEY,
    requisicao: {
      systemInstruction: { parts: [{ text: prompt }] },
      contents: [{ role: 'user', parts: [{ text: `<certificado>\n${certificado}\n</certificado>` }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: schema },
    },
  },
}];

// Sem GEMINI_API_KEY: devolve uma classificação de demonstração por palavras-chave, no mesmo
// formato da resposta do Gemini, para testar o resto do fluxo. A página avisa que é simulação.
const texto = $input.first().json.texto_anonimizado;
const t = texto.toLowerCase();
const horas = Number((t.match(/(\d+(?:[.,]\d+)?)\s*h(?:oras)?\b/) ?? [])[1]?.replace(',', '.')) || null;

let tipo = 'Curso extracurricular na área de concentração do curso';
if (/palestra|webinar/.test(t)) tipo = 'Palestra na área de concentração do curso';
else if (/ingl[eê]s|espanhol|idioma|english/.test(t)) tipo = 'Curso de Línguas Estrangeiras';

const classificacao = {
  e_comprovante: true,
  tipo_sigaa: tipo,
  variante: 'padrao',
  quantidades: { horas, dias: null, meses: null, semestres: null, anos: null },
  atividade: 'Atividade do certificado (simulação)',
  instituicao: 'Não identificada (simulação)',
  periodo: '',
  ano_conclusao: null,
  papel: 'participante',
  descricao_sigaa: 'Classificação simulada: configure GEMINI_API_KEY para a análise real.',
  confianca: 'baixa',
  justificativa: 'Modo demonstração: classificação por palavras-chave, sem modelo de IA.',
  alternativas: [],
  evidencia_faltante: null,
  alerta_instrucao_suspeita: false,
};

return [{
  json: {
    simulado: true,
    statusCode: 200,
    body: {
      candidates: [{ content: { parts: [{ text: JSON.stringify(classificacao) }] } }],
      usageMetadata: { promptTokenCount: 0, candidatesTokenCount: 0 },
    },
  },
}];

// Valida a resposta do modelo e calcula as horas pela tabela regras/categorias-cl2023t.json.
// O modelo só escolhe categoria, variante e quantidades; toda conta é feita aqui.
const fs = require('fs');
const regras = JSON.parse(fs.readFileSync('/data/regras/categorias-cl2023t.json', 'utf8'));
const base = $('Montar requisição').first().json;
const r = $input.first().json;

const num = (v) => Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 2 });
const arred = (v) => Math.round(v * 100) / 100;
const UNIDADE = { por_hora: 'horas', por_dia: 'dias', por_mes: 'meses', por_semestre: 'semestres', por_ano: 'anos' };

function calcular(regras, c) {
  const cat = regras.categorias.find((x) => x.tipo_sigaa === c.tipo_sigaa);
  if (!cat) return { status: 'a_confirmar', motivo: 'Categoria sem regra cadastrada.' };

  const tetoPct = cat.teto_pct[c.variante] ?? cat.teto_pct.padrao;
  const resultado = {
    status: 'confirmado',
    teto_pct: tetoPct,
    teto_ha: arred((regras.total_ac_ha * tetoPct) / 100),
    total_ac_ha: regras.total_ac_ha,
    norma: cat.norma === 'cgrad05_23' ? 'Resolução CGRAD 05/23' : 'Resolução CGRAD 19/11',
    artigo: cat.artigo,
    url_fonte: regras.fontes[cat.norma],
    observacao: cat.observacao ?? null,
    ha_calculadas: null,
    ha_abatidas: null,
    conta: null,
  };
  if (cat.calculo === 'a_definir') {
    return { ...resultado, status: 'a_confirmar', motivo: 'A norma não define a fórmula: a Coordenação decide o valor.' };
  }

  const k = cat.k[c.variante] ?? cat.k.padrao;
  if (k === undefined) {
    return { ...resultado, status: 'a_confirmar', motivo: `Não sei qual fator usar (variante "${c.variante}").` };
  }

  const unidade = UNIDADE[cat.calculo];
  const qtd = unidade ? Number(c.quantidades?.[unidade]) : 1;
  if (unidade && !(qtd > 0)) {
    return { ...resultado, status: 'a_confirmar', motivo: `O certificado não informa ${unidade === 'horas' ? 'a carga horária' : `o número de ${unidade}`}.` };
  }

  let ha;
  let conta;
  if (cat.calculo === 'por_hora') {
    const fator = cat.ha_por_hora ?? 1.2;
    ha = k * qtd * fator;
    conta = `${num(qtd)} h × K ${num(k)} × ${num(fator)}`;
  } else if (cat.calculo === 'por_dia') {
    ha = k * 9.6 * qtd;
    conta = `${num(qtd)} dia(s) × 9,6 × K ${num(k)}`;
  } else if (cat.calculo === 'fixo') {
    ha = k * cat.base_ha;
    conta = `${num(cat.base_ha)} h/a × K ${num(k)}`;
  } else {
    ha = k * cat.base_ha * qtd;
    conta = `${num(qtd)} ${unidade} × ${num(cat.base_ha)} h/a × K ${num(k)}`;
  }
  ha = arred(ha);
  return {
    ...resultado,
    ha_calculadas: ha,
    ha_abatidas: Math.min(ha, resultado.teto_ha),
    limitado_pelo_teto: ha > resultado.teto_ha,
    conta: `${conta} = ${num(ha)} h/a`,
  };
}

const falha = (erro) => [{ json: { origem: base.origem, modo: base.modo, erro } }];

if (r.statusCode === 429) return falha('O limite gratuito do modelo de IA acabou por agora. Tente de novo em alguns minutos.');
if (r.statusCode === 503) return falha('O modelo de IA está sobrecarregado agora. Tente de novo em alguns minutos.');
if (r.statusCode === undefined && /timeout|aborted/i.test(r.error?.message ?? '')) {
  return falha('O modelo de IA demorou demais para responder. Tente de novo.');
}
if (r.statusCode !== 200) return falha(`O modelo de IA não respondeu (erro ${r.statusCode ?? 'de rede'}). Tente de novo.`);

let c;
try {
  c = JSON.parse(r.body.candidates[0].content.parts[0].text);
} catch (e) {
  return falha('O modelo de IA devolveu uma resposta fora do formato. Tente de novo.');
}
if (!c.e_comprovante) {
  return falha(`Este arquivo não parece um certificado ou comprovante de atividade. ${c.justificativa ?? ''}`.trim());
}

const horas = Number(c.quantidades?.horas);
const uso = r.body.usageMetadata ?? {};
return [{
  json: {
    origem: base.origem,
    modo: base.modo,
    versao: base.versao,
    modelo: base.modelo,
    simulado: Boolean(r.simulado),
    linha_data: base.linha_data,
    classificacao: c,
    calculo: calcular(regras, c),
    ha_certificado: horas > 0 ? arred(horas * 1.2) : null,
    tokens: { entrada: uso.promptTokenCount ?? 0, saida: uso.candidatesTokenCount ?? 0 },
    erro: '',
  },
}];

// Declaração datada + certificado. O Gotenberg junta em ordem alfabética do nome do arquivo.
const prep = $('Preparar certificado').first();
const declaracao = await this.helpers.prepareBinaryData(
  Buffer.from(prep.json.declaracao_datada_b64, 'base64'), '1_declaracao.pdf', 'application/pdf',
);
return [{
  json: $input.first().json,
  binary: { declaracao, certificado: { ...prep.binary.certificado, fileName: '2_certificado.pdf' } },
}];

// Página de resultado: o que marcar no SIGAA, quantas horas abatem e os PDFs para baixar.
// O formulário do n8n troca o corpo da página por este HTML (sem scripts), então tudo é estático.
const r = $('Validar e calcular').first().json;
const final = $input.first().binary?.pdf_final;
if (!final) throw new Error(`Gotenberg não juntou os PDFs: ${$input.first().json.error?.message ?? 'sem resposta'}`);

const c = r.classificacao;
const calc = r.calculo;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (ch) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]
));
const num = (v) => Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 2 });
const slug = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^\w]+/g, '_').replace(/^_|_$/g, '').slice(0, 50) || 'atividade';

const pdfFinal = (await this.helpers.getBinaryDataBuffer(0, 'pdf_final')).toString('base64');
const pdfBase = r.modo === 'primeiro_uso' ? $('Guardar base').first().json.declaracao_base_b64 : null;

const horas = calc.ha_abatidas !== null
  ? `<p class="valor">${num(calc.ha_abatidas)} h/a</p>
     <p class="conta">${esc(calc.conta)}${calc.limitado_pelo_teto ? ` → limitado ao teto de ${num(calc.teto_ha)} h/a` : ''}</p>`
  : `<p class="valor pendente">A confirmar</p><p class="conta">${esc(calc.motivo)} Confirme com a Coordenação.</p>`;

const alertas = [];
if (r.simulado) alertas.push('<strong>Modo demonstração:</strong> sem chave do Gemini, a classificação foi feita por palavras-chave. Não use este resultado.');
if (c.alerta_instrucao_suspeita) alertas.push('O certificado contém um texto que tenta instruir a IA. Ele foi ignorado, mas confira se o documento é legítimo.');
if (c.confianca !== 'alta') alertas.push(`Confiança <strong>${esc(c.confianca)}</strong>: ${esc(c.justificativa)}${c.alternativas?.length ? ` Outras opções possíveis: ${c.alternativas.map(esc).join('; ')}.` : ''}`);
if (c.evidencia_faltante) alertas.push(`Falta no certificado: ${esc(c.evidencia_faltante)}`);

const html = `
<style>
  #hc { max-width: 680px; margin: 24px auto; padding: 0 16px; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #1f2328; line-height: 1.5; }
  #hc h1 { font-size: 22px; margin: 0 0 4px; }
  #hc .sub { color: #59636e; margin: 0 0 20px; }
  #hc .destaque { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
  #hc .card { border: 1px solid #d1d9e0; border-radius: 10px; padding: 14px 16px; background: #fff; }
  #hc .rotulo { font-size: 12px; text-transform: uppercase; letter-spacing: .04em; color: #59636e; margin: 0 0 4px; }
  #hc .tipo { font-size: 17px; font-weight: 650; margin: 0; }
  #hc .valor { font-size: 28px; font-weight: 700; margin: 0; color: #1a7f37; }
  #hc .valor.pendente { color: #9a6700; font-size: 22px; }
  #hc .conta { font-size: 13px; color: #59636e; margin: 4px 0 0; }
  #hc .alerta { border-left: 4px solid #d4a72c; background: #fff8c5; padding: 10px 12px; border-radius: 6px; margin: 0 0 10px; font-size: 14px; }
  #hc dl { display: grid; grid-template-columns: max-content 1fr; gap: 6px 14px; margin: 0; font-size: 14px; }
  #hc dt { color: #59636e; }
  #hc dd { margin: 0; }
  #hc textarea { width: 100%; box-sizing: border-box; font: inherit; font-size: 14px; padding: 8px; border: 1px solid #d1d9e0; border-radius: 6px; resize: vertical; }
  #hc .botoes { display: flex; flex-wrap: wrap; gap: 10px; margin: 18px 0; }
